1611	    async fn stop_all_workers(&self) {
1612	        let workers = {
1613	            let mut runtimes = self.runtimes.lock().await;
1614	            runtimes
1615	                .values_mut()
1616	                .filter_map(|runtime| {
1617	                    if matches!(
1618	                        runtime.state,
1619	                        SshForwardState::Starting
1620	                            | SshForwardState::Running
1621	                            | SshForwardState::Reconnecting
1622	                    ) {
1623	                        runtime.suspended = true;
1624	                        runtime.state = SshForwardState::Stopped;
1625	                        runtime.error_code = None;
1626	                        runtime.changed_at = UtcTimestamp::now();
1627	                    }
1628	                    let stop_tx = runtime.stop_tx.take();
1629	                    runtime.worker.take().map(|worker| (stop_tx, worker))
1630	                })
1631	                .collect::<Vec<_>>()
1632	        };
1633	        self.close_workers(workers).await;
