1651	    async fn close_workers(
1652	        &self,
1653	        mut workers: Vec<(Option<oneshot::Sender<Instant>>, JoinHandle<()>)>,
1654	    ) {
1655	        let deadline = Instant::now() + WORKER_SHUTDOWN_GRACE;
1656	        for (stop_tx, _) in &mut workers {
1657	            if let Some(stop_tx) = stop_tx.take() {
1658	                let _ = stop_tx.send(deadline);
1659	            }
1660	        }
1661	
1662	        // Reserve time to abort and join every outstanding worker. A worker owns its
1663	        // listener, SSH session, and channel JoinSet, so its join is the disposal proof.
1664	        let reap_start = deadline - WORKER_REAP_RESERVE;
1665	        let mut next = 0;
1666	        while next < workers.len() {
1667	            let remaining = reap_start.saturating_duration_since(Instant::now());
1668	            if remaining.is_zero() || timeout(remaining, &mut workers[next].1).await.is_err() {
1669	                break;
1670	            }
1671	            next += 1;
1672	        }
1673	        if next == workers.len() {
1674	            return;
1675	        }
1676	
1677	        for (_, worker) in workers.iter().skip(next) {
1678	            worker.abort();
1679	        }
1680	        for (_, worker) in workers.iter_mut().skip(next) {
1681	            let remaining = deadline.saturating_duration_since(Instant::now());
1682	            if remaining.is_zero() {
1683	                break;
1684	            }
1685	            let _ = timeout(remaining, worker).await;
1686	        }
1687	    }
